return [{ json: { workflowStatus: 'REPORT_GENERATED', generatedAt: new Date().toISOString(), dashboardStatus: $json.dashboardStatus, summary: `Daily Report

Leads Captured: ${$json.leadsCaptured}
Hot Leads: ${$json.hotLeads}
Outreach Sent: ${$json.outreachSent}
Replies: ${$json.replies}
Booked Calls: ${$json.bookedCalls}
Revenue: $${$json.revenue}
Conversion Rate: ${$json.conversionRate}
Reply Rate: ${$json.replyRate}
Hot Lead Rate: ${$json.hotLeadRate}`, message: 'Replace this node with Gmail, Outlook, Slack, Microsoft Teams, Discord, or another reporting destination.' } }];

const leads = Number($json.leadsCaptured || 0);
const hot = Number($json.hotLeads || 0);
const outreach = Number($json.outreachSent || 0);
const replies = Number($json.replies || 0);
const calls = Number($json.bookedCalls || 0);
const revenue = Number($json.revenue || 0);

const conversionRate = leads ? ((calls / leads) * 100).toFixed(2) : '0.00';
const replyRate = outreach ? ((replies / outreach) * 100).toFixed(2) : '0.00';
const hotLeadRate = leads ? ((hot / leads) * 100).toFixed(2) : '0.00';

const formattedDate = new Date().toLocaleString('en-US', {
  timeZone: 'America/Chicago',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: 'numeric',
  minute: '2-digit',
  hour12: true,
});

return [
  {
    json: {
      date: formattedDate,
      leadsCaptured: leads,
      hotLeads: hot,
      outreachSent: outreach,
      replies,
      bookedCalls: calls,
      revenue,
      conversionRate: conversionRate + '%',
      replyRate: replyRate + '%',
      hotLeadRate: hotLeadRate + '%'
    }
  }
];
